import{_ as a,o as d,c as r,a2 as i}from"./chunks/framework.DkXPQl_e.js";const u=JSON.parse('{"title":"DIC 考点版笔记","description":"","frontmatter":{},"headers":[],"relativePath":"exam-focus/index.md","filePath":"exam-focus/index.md","lastUpdated":null}'),e={name:"exam-focus/index.md"};function l(o,t,n,s,h,c){return d(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="dic-考点版笔记" tabindex="-1">DIC 考点版笔记 <a class="header-anchor" href="#dic-考点版笔记" aria-label="Permalink to &quot;DIC 考点版笔记&quot;">​</a></h1><blockquote><p>依据：2022、2023、2024、2025 四份 UESTC4033 真题，以及已经整理好的 lecture notes。<br> 说明：这里的“高频/低频”只代表这四年真题的直接证据，不等于以后绝对这样考。</p></blockquote><p>这套笔记是 <strong>考点版</strong>，不是 PPT 顺序版。写法以中文为主，只在专业术语、公式、VHDL 代码和题目常用关键词中保留英文。重要英文术语第一次出现时会给中文注释，例如：开关点（switching point）、版图（layout）、迟滞（hysteresis）。</p><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><ul><li><a href="./part1_introduction_history_fundamentals.html">Part 1：Introduction, History &amp; Fundamentals</a></li><li><a href="./part2_simulations_layout.html">Part 2：Simulations &amp; Layout</a></li><li><a href="./part3_analog_digital_blocks.html">Part 3：Analog and Digital Blocks</a></li><li><a href="./part4_exam_preparation.html">Part 4：Exam Preparation</a></li></ul><h2 id="考点分布" tabindex="-1">考点分布 <a class="header-anchor" href="#考点分布" aria-label="Permalink to &quot;考点分布&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>考点</th><th>主要来源</th><th>真题证据</th></tr></thead><tbody><tr><td>最高</td><td>施密特触发器设计（Schmitt trigger design）</td><td>Part 3</td><td>2022-2025 每年都考</td></tr><tr><td>最高</td><td>VHDL 读写与电路转换</td><td>Part 2 / Part 4</td><td>2022-2025 每年都考</td></tr><tr><td>最高</td><td>CMOS 开关点/尺寸计算（switching point / sizing）</td><td>Part 1 / Part 3 / Part 4</td><td>2022-2025 每年都考</td></tr><tr><td>高</td><td>混合信号设计流程（mixed-signal design flow）</td><td>Part 1</td><td>2022、2024、2025</td></tr><tr><td>高</td><td>AOI/OAI 晶体管级实现</td><td>Part 3 / Part 4</td><td>2023、2024、2025</td></tr><tr><td>高</td><td>信号调理（signal conditioning）</td><td>Part 3</td><td>2022、2023、2024</td></tr><tr><td>高</td><td>版图与可靠性（layout / reliability）</td><td>Part 2 / Part 3</td><td>2023、2024、2025</td></tr><tr><td>中高</td><td>模数转换器（ADC）</td><td>Part 3</td><td>2025</td></tr><tr><td>低直接证据</td><td>SPICE、发展史、dB、电流镜、差分对、频率响应、传输门、锁存器、DAC</td><td>多个 Part</td><td>四年未见直接大题</td></tr></tbody></table><h2 id="复习顺序" tabindex="-1">复习顺序 <a class="header-anchor" href="#复习顺序" aria-label="Permalink to &quot;复习顺序&quot;">​</a></h2><ol><li>先读 Part 4，知道题目通常怎么问。</li><li>再读 Part 3 的 Schmitt trigger、CMOS logic、ADC。</li><li>同步看 Part 2 的 VHDL 和 layout。</li><li>最后回 Part 1 补 design flow、MOS 模型、analog vs digital 背景。</li></ol><h2 id="特别提醒" tabindex="-1">特别提醒 <a class="header-anchor" href="#特别提醒" aria-label="Permalink to &quot;特别提醒&quot;">​</a></h2><p>2025 Q1(d) 考了 <strong>Flash ADC vs Pipeline ADC</strong>。原 lecture 笔记里 Flash、SAR、Dual-slope 比较完整，但 Pipeline ADC 不够展开。本考点版已经补了流水线 ADC（Pipeline ADC）的结构、速度/分辨率/功耗比较和答题模板。</p>',11)])])}const p=a(e,[["render",l]]);export{u as __pageData,p as default};
